#!/bin/bash\n\n# XSpoof APK Build Script\n# Quick build for debug and release APKs\n\nset -e\n\necho \"🔨 XSpoof APK Builder\"\necho \"=====================\"\n\n# Colors\nGREEN='\\033[0;32m'\nBLUE='\\033[0;34m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color\n\n# Check if gradlew exists\nif [ ! -f \"gradlew\" ]; then\n    echo -e \"${YELLOW}⚠️  gradlew not found. Creating...${NC}\"\n    chmod +x gradlew\nfi\n\necho -e \"${BLUE}📱 Select build type:${NC}\"\necho \"1) Debug APK (for testing)\"\necho \"2) Release APK (unsigned)\"\necho \"3) Both\"\nread -p \"Enter choice (1-3): \" choice\n\necho -e \"${BLUE}🧹 Cleaning previous builds...${NC}\"\n./gradlew clean\n\ncase $choice in\n    1)\n        echo -e \"${BLUE}🔨 Building Debug APK...${NC}\"\n        ./gradlew assembleDebug\n        echo -e \"${GREEN}✅ Debug APK built successfully!${NC}\"\n        echo -e \"${GREEN}📍 Location: app/build/outputs/apk/debug/app-debug.apk${NC}\"\n        echo \"\"\n        echo -e \"${BLUE}📦 Installation:${NC}\"\n        echo \"adb install app/build/outputs/apk/debug/app-debug.apk\"\n        ;;\n    2)\n        echo -e \"${BLUE}🔨 Building Release APK (unsigned)...${NC}\"\n        ./gradlew assembleRelease\n        echo -e \"${GREEN}✅ Release APK built successfully!${NC}\"\n        echo -e \"${GREEN}📍 Location: app/build/outputs/apk/release/app-release.apk${NC}\"\n        echo \"\"\n        echo -e \"${YELLOW}⚠️  Note: Release APK is unsigned. You need to sign it before distribution.${NC}\"\n        ;;\n    3)\n        echo -e \"${BLUE}🔨 Building Debug APK...${NC}\"\n        ./gradlew assembleDebug\n        echo -e \"${GREEN}✅ Debug APK built!${NC}\"\n        \n        echo -e \"${BLUE}🔨 Building Release APK...${NC}\"\n        ./gradlew assembleRelease\n        echo -e \"${GREEN}✅ Release APK built!${NC}\"\n        \n        echo \"\"\n        echo -e \"${GREEN}📦 Both APKs ready:${NC}\"\n        echo -e \"${GREEN}Debug:   app/build/outputs/apk/debug/app-debug.apk${NC}\"\n        echo -e \"${GREEN}Release: app/build/outputs/apk/release/app-release.apk${NC}\"\n        ;;\n    *)\n        echo -e \"${YELLOW}Invalid choice!${NC}\"\n        exit 1\n        ;;\nesac\n\necho \"\"\necho -e \"${BLUE}📋 Build Summary:${NC}\"\nls -lh app/build/outputs/apk/*/*.apk 2>/dev/null || echo \"No APKs found\"\n\necho \"\"\necho -e \"${GREEN}✨ Done!${NC}\"\n"